{{(() => {
    // Calculate total from delivered and returned orders (both billable)
    const orders = ServiceBillingReport.data || [];
    const billableOrders = orders.filter(order =>
      order.billing_status === 'Billable - Delivered ✅' ||
      order.billing_status === 'Billable - Returned ↩️'
    );

    // order_fee_usd is service_quotes.amount / 100, and every service rate and quote in
    // this deployment is EUR (Bulgaria adopted the euro on 2026-01-01). The figure is
    // already in euro - do not convert it.
    const totalEUR = billableOrders.reduce((sum, order) =>
      sum + (parseFloat(order.order_fee_usd) || 0), 0
    );

    // NOT what the merchant owes. Their shoppers paid delivery and the наложен платеж
    // fee at checkout, so this is what Fulfilya keeps out of the cash its drivers
    // collected - the deduction, not an invoice. Nothing is billed to the merchant.
    return `💰 Fulfilya keeps (delivery + наложен платеж): ${totalEUR.toFixed(2)} EUR`;
  })()}}
